content:
{
 "kind": "sequence",
 "format": 1,
 "id": "seq_cphl_booth_open",
 "name": "Cluster Puck: the booth, before the puck drop",
 "set": "set_slush_booth",
 "roles": {
  "pbp": {
   "mark": "pbp",
   "label": "Play-by-play"
  },
  "col": {
   "mark": "col",
   "label": "Colour"
  }
 },
 "wall": "feed",
 "wallText": "{venue}",
 "wallSub": "{show}",
 "beats": [
  {
   "id": "b1",
   "shot": {
    "cam": "wide",
    "frame": "two",
    "on": [
     "pbp",
     "col"
    ],
    "move": "drift",
    "cut": "dissolve"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "We're up on the gantry at {venue}, and it's loud already. I'm {pbp.name}, with {col.name}.",
     "Hello from {venue}. {pbp.name} and {col.name} with you."
    ]
   },
   "gfx": [
    {
     "kind": "lower",
     "text": "{pbp.name} and {col.name}",
     "sub": "The call from {venue}",
     "at": 0.4,
     "for": 5
    }
   ]
  },
  {
   "id": "b2",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "{away} come in at {awayRecord}. {home} are {homeRecord}. Neither one can coast tonight.",
     "{home} are {homeRecord} and {away} {awayRecord}. Points are points."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "awayRecord",
     "op": "has"
    },
    {
     "fact": "homeRecord",
     "op": "has"
    }
   ]
  },
  {
   "id": "b3",
   "shot": {
    "cam": "cam3",
    "frame": "close",
    "on": [
     "col"
    ],
    "move": "push",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "Watch {star.name}. He's got {star.said}, and he wants more.",
     "{star.name} is the one. {star.said} so far."
    ]
   },
   "gfx": [
    {
     "kind": "profile",
     "who": "star",
     "side": "right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "star.name",
     "op": "has"
    },
    {
     "fact": "star.said",
     "op": "has"
    }
   ]
  },
  {
   "id": "b4",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "{awayGoalie.name} is in net for {away}. {homeGoalie.name} for {home}.",
     "In goal it's {homeGoalie.name} for {home} and {awayGoalie.name} for {away}."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "awayGoalie.name",
     "op": "has"
    },
    {
     "fact": "homeGoalie.name",
     "op": "has"
    }
   ]
  },
  {
   "id": "b5",
   "shot": {
    "cam": "cam1",
    "frame": "two",
    "on": [
     "pbp",
     "col"
    ],
    "move": "pull",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "Puck drop's next. Here we go.",
     "They're lining up for the opening draw."
    ]
   },
   "gfx": []
  }
 ]
}
